 const categories=({push:['Chest','Shoulders','Arms'],pull:['Back','Shoulders','Arms'],legs:['Legs','Core'],upper:['Chest','Back','Shoulders','Arms'],lower:['Legs','Core'],full:['Chest','Back','Legs','Shoulders','Arms','Core']})[pref.day]||[];
